$ErrorActionPreference='Stop';$root=Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path);& (Join-Path $root 'build-tools/build.ps1') --only java;if($LASTEXITCODE -ne 0){exit $LASTEXITCODE};$jar=Get-ChildItem (Join-Path $root 'build') -Recurse -Filter *.jar -ErrorAction SilentlyContinue|Select-Object -First 1;if($jar){Write-Host "[RUN] java -jar $($jar.FullName)";& java -jar $jar.FullName;exit $LASTEXITCODE};Write-Host '[RUN] No packaged Java JAR detected; compilation completed.'
